import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { SYSTEM_SCOUT_NAMES } from 'lib/constants'
import { teamLogic } from 'scenes/teamLogic'
import { userLogic } from 'scenes/userLogic'

import { signalsScoutConfigList } from 'products/signals/frontend/generated/api'
import type { SignalScoutConfigApi } from 'products/signals/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutPickerLogicValues {
    currentTeamId: number | null // teamLogic
    scoutConfigs: SignalScoutConfigApi[]
    scoutConfigsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutPickerLogicActions {
    loadScoutConfigs: () => any
    loadScoutConfigsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadScoutConfigsSuccess: (
        scoutConfigs: SignalScoutConfigApi[],
        payload?: any
    ) => {
        scoutConfigs: SignalScoutConfigApi[]
        payload?: any
    }
}

export type scoutPickerLogicType = MakeLogicType<scoutPickerLogicValues, scoutPickerLogicActions>

export const scoutPickerLogic = kea<scoutPickerLogicType>([
    path(['products', 'signals', 'frontend', 'components', 'ScoutPicker', 'scoutPickerLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        scoutConfigs: [
            [] as SignalScoutConfigApi[],
            {
                loadScoutConfigs: async (): Promise<SignalScoutConfigApi[]> => {
                    if (!values.currentTeamId) {
                        return []
                    }
                    const configs = await signalsScoutConfigList(String(values.currentTeamId))
                    return configs.filter(
                        (config) => userLogic.values.user?.is_staff || !SYSTEM_SCOUT_NAMES.includes(config.skill_name)
                    )
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadScoutConfigs()
    }),
])
